-- #195 : vrais referentiels IRT et Gestion (matieres, niveaux, options), en remplacement de
-- l'echantillon fictif de supabase/seed.sql. Idempotent (executable plusieurs fois sans doublon) :
-- requetes par nom, jamais par id fixe (les ids fictifs deja en base, prod comme dev, ne
-- correspondent a aucun id attendu ici).

do $$
declare
  irt_id uuid;
  gestion_id uuid;
  l1_id uuid;
  l2_id uuid;
  l3_id uuid;
begin
    select name from (values ('L1'), ('L2'), ('L3'), ('M1'), ('M2')) as v(name)
    where not exists (select 1 from public.levels where levels.name = v.name);

    select 'Informatique, Réseaux et Télécommunications'
    where not exists (select 1 from public.fields where name = 'Informatique, Réseaux et Télécommunications');
    select 'Gestion' where not exists (select 1 from public.fields where name = 'Gestion');

  select id into irt_id from public.fields where name = 'Informatique, Réseaux et Télécommunications';
  select id into gestion_id from public.fields where name = 'Gestion';
  select id into l1_id from public.levels where name = 'L1';
  select id into l2_id from public.levels where name = 'L2';
  select id into l3_id from public.levels where name = 'L3';

  -- IRT a 3 options a partir du S4 (AL, SI, SRC), pas 2 (AL, SRS) comme actuellement en base :
  -- corrige l'option existante plutot que d'en laisser une fausse a cote de la bonne.
  update public.options set name = 'Systèmes Réseaux et Cloud (SRC)'
    where field_id = irt_id and name = 'Systèmes, Réseaux et Sécurité (SRS)';
    select irt_id, 'Architecture Logicielle (AL)'
    where not exists (select 1 from public.options where field_id = irt_id and name = 'Architecture Logicielle (AL)');
    select irt_id, 'Sécurité Informatique (SI)'
    where not exists (select 1 from public.options where field_id = irt_id and name = 'Sécurité Informatique (SI)');
    select irt_id, 'Systèmes Réseaux et Cloud (SRC)'
    where not exists (select 1 from public.options where field_id = irt_id and name = 'Systèmes Réseaux et Cloud (SRC)');
    select gestion_id, 'Comptabilité, Contrôle, Audit (CCA)'
    where not exists (select 1 from public.options where field_id = gestion_id and name = 'Comptabilité, Contrôle, Audit (CCA)');

  -- Remplace l'echantillon fictif de L1 a L3 par le vrai programme : M1/M2 restent hors perimetre
  -- (programmes pas encore fournis), jamais touches ici. Sans danger pour des epreuves deja
  -- deposees : la FK `on delete restrict` d'exams vers subjects ferait echouer la migration plutot
  -- que de les laisser orphelines.
  delete from public.subjects
    where field_id in (irt_id, gestion_id) and level_id in (l1_id, l2_id, l3_id);

end $$;
